<?php

defined('BASEPATH') or exit('No direct script access allowed');
class Company_sales extends AdminController
{
    public function index()
    {
        if(!CompanyRequestScope::sealedFor($this)){show_error('Contexto indisponível.',503);return;}
        require_once APPPATH.'services/CompanySales.php';require_once APPPATH.'services/CompanySalesExtrasHttp.php';require_once APPPATH.'services/CompanyClients.php';require_once APPPATH.'services/CompanyContactSalesAccess.php';
        $ctx=CompanyRequestScope::context();$issuer=$ctx->issuerId();$actor=$ctx->staffId();$acl=new IssuerResourceAccess($this->db,db_prefix());$kind=$this->input->get('kind',false)??'estimates';if(!in_array($kind,['estimates','proposals'],true)||!$acl->can($issuer,$actor,$kind,'view')){show_error('Documento indisponível nesta empresa.',403);return;}
        $this->output->set_header('Cache-Control: no-store');$s=new CompanySales($this->db,db_prefix());$portal_permissions=[];$search='';$error=null;$detail=null;$directory=['items'=>[],'next'=>null];$clients=[];$currencies=[];$csrf=$this->session->userdata('company_sales_csrf');if(!is_string($csrf)||strlen($csrf)!==64){$csrf=bin2hex(random_bytes(32));$this->session->set_userdata('company_sales_csrf',$csrf);}
        try{
            if($this->input->method(true)==='POST'){
                $token=$this->input->post('company_sales_csrf',false);if(!is_string($token)||!hash_equals($csrf,$token)){show_error('Recarregue antes de salvar.',403);return;}$action=$this->input->post('action',false);$id=$this->input->post('document_id',false);
                if(CompanySalesExtrasHttp::post($this,$issuer,$actor,$id,$action)){}
                elseif($action==='create'){$input=$this->input->post('invoice',false);$key=$this->input->post('request_key',false);if(!is_array($input)||!is_string($key))throw new DomainException('company_sales_invalid');$id=$s->create($issuer,$actor,$kind,$input,$key);}
                elseif($action==='portal_permission'){$document=$s->document($issuer,$actor,$id);if($document['kind']!==$kind)throw new DomainException('company_sales_denied');$contact=$this->input->post('contact_id',false);$revision=$this->input->post('revision',false);$allowed=$this->input->post('allowed',false)??'0';if(!is_string($revision)||!is_string($allowed))throw new DomainException('company_sales_invalid');(new CompanyContactSalesAccess($this->db,db_prefix(),$kind))->set($issuer,$actor,$document['payload']['client_id'],$contact,$revision,$allowed);}
                elseif($action==='convert')$s->convert($issuer,$actor,$id);
                elseif(in_array($action,['accepted','declined','cancelled'],true))$s->decide($issuer,$actor,$id,$action);else throw new DomainException('company_sales_invalid');
                CompanyRequestScope::invalidateCaches($this);redirect(CompanyRequestScope::adminUrl($this,'company_sales?kind='.$kind.'&document='.(int)$id),'location',303);return;
            }elseif(!in_array($this->input->method(true),['GET','HEAD'],true)){show_error('Método não permitido.',405);return;}
            $id=$this->input->get('document',false);if($id!==null){$detail=$s->document($issuer,$actor,$id);if($detail['kind']!==$kind)throw new DomainException('company_sales_denied');if(CompanySalesExtrasHttp::download($this,$issuer,$actor,$id))return;if($this->input->get('pdf',false)==='1'){require_once APPPATH.'vendor/tecnickcom/tcpdf/tcpdf.php';require_once APPPATH.'services/CompanySalesPdf.php';$pdf=CompanySalesPdf::prepare($detail);$s->confirmPdf($issuer,$actor,$id);$pdf->Output('documento-'.(int)$id.'.pdf','D');return;}if($acl->can($issuer,$actor,'customers','view')){try{$portal_permissions=(new CompanyContactSalesAccess($this->db,db_prefix(),$kind))->page($issuer,$actor,$detail['payload']['client_id']);}catch(DomainException $unavailable){$portal_permissions=[];}}}
            $search=$this->input->get('search',false)??'';if(!is_string($search))throw new DomainException('company_sales_invalid');$directory=$s->page($issuer,$actor,$kind,$this->input->get('after',false)??0,$search);if($acl->can($issuer,$actor,$kind,'create')&&$acl->can($issuer,$actor,'customers','view')){$clients=(new CompanyClients($this->db,db_prefix()))->page($issuer,$actor,0,100)['items'];$currencies=$s->currencies($issuer,$actor,$kind);}
        }catch(DomainException $e){if(str_contains($e->getMessage(),'denied')){show_error('Documento indisponível nesta empresa.',403);return;}$this->output->set_status_header(str_contains($e->getMessage(),'conflict')||str_contains($e->getMessage(),'stale')?409:422);$error=match($e->getMessage()){'company_sales_file_invalid'=>'Envie PDF até 2 MiB ou PNG/JPEG até 512 KiB e 1600 pixels. O nome não pode conter caminhos.','company_sales_file_limit'=>'O documento atingiu o limite histórico de 20 uploads ou 20 MiB. Ocultar preserva a quota.','company_sales_delivery_template_required'=>'Ative o template próprio de envio de orçamento/proposta e mantenha o link do documento.','company_sales_delivery_sender_required','company_mail_configuration_required','company_mail_secret_unavailable'=>'Complete a configuração SMTP desta empresa antes de agendar.','company_sales_stale'=>'O documento mudou. Reabra antes de agendar a notificação.',default=>null};if($error===null)$error=$e->getMessage()==='company_sales_origin_changed'?'A identidade, destinatário ou configuração mudou desde a emissão. Preserve este documento e crie outro com a origem atual antes de converter.':'Confira os campos, as permissões e o estado do documento. Nenhuma conclusão financeira foi presumida.';}
        catch(Throwable $e){log_message('error','Company sales operation unconfirmed; no document values logged.');$this->output->set_status_header(503);$error='Operação não confirmada. Reabra o documento; a conversão pode ser retomada com a mesma origem.';}
        $this->load->view('admin/companies/sales',['portal_permissions'=>$portal_permissions,'can_contact_edit'=>$acl->can($issuer,$actor,'customers','edit'),'search'=>$search,'kind'=>$kind,'issuer'=>$issuer,'detail'=>$detail,'directory'=>$directory,'clients'=>$clients,'currencies'=>$currencies,'error'=>$error,'company_sales_csrf'=>$csrf,'can_create'=>$acl->can($issuer,$actor,$kind,'create'),'can_edit'=>$acl->can($issuer,$actor,$kind,'edit'),'can_delete'=>$acl->can($issuer,$actor,$kind,'delete'),'can_convert'=>$acl->can($issuer,$actor,'invoices','create')]);
    }
}
